import {useEffect,useRef,useState} from 'react';
import type {LocalTextApi} from '../text-ai/api.js';
type Session=Awaited<ReturnType<LocalTextApi['session']>>;
export function McpPanel({api,session,refresh,proposal}:{api:LocalTextApi;session:Session|null;refresh:()=>Promise<void>;proposal?:{name:string;arguments:Record<string,unknown>}}){
 const info=session?.mcpConnection,manifest=info?.manifest;
 const [names,setNames]=useState<string[]>(info?.approved??[]),[verified,setVerified]=useState(false),[tool,setTool]=useState(''),[args,setArgs]=useState('{}'),[consent,setConsent]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState(''),[result,setResult]=useState('');
 const job=useRef<{id:string;controller:AbortController}|null>(null),alive=useRef(true),epoch=useRef(0);
 useEffect(()=>{epoch.current++;job.current?.controller.abort();setBusy(false);setNames(info?.approved??[]);setVerified(false);setConsent(false);setResult('');},[info?.roundId,info?.id]);
 useEffect(()=>{if(proposal){setTool(proposal.name);setArgs(JSON.stringify(proposal.arguments,null,2));setConsent(false);}},[proposal]);
 useEffect(()=>()=>{alive.current=false;job.current?.controller.abort();},[]);
 async function approve(){if(!info||!manifest)return;const generation=epoch.current;setError('');try{await api.write('/api/mcp/approve',{connectionId:info.id,manifestId:manifest.id,names,readOnlyAcknowledged:true});await refresh();}catch(error){if(generation===epoch.current&&alive.current)setError(error instanceof Error?error.message:'授权失败。');}}
 async function call(){if(!info||!manifest)return;const generation=epoch.current,active={id:crypto.randomUUID(),controller:new AbortController()};job.current=active;setBusy(true);setResult('');setError('');
  try{const value:unknown=JSON.parse(args);const response=await api.write('/api/mcp/call',{connectionId:info.id,manifestId:manifest.id,roundId:info.roundId,name:tool,arguments:value,consent:true,requestId:active.id},'POST',active.controller.signal);if(alive.current&&generation===epoch.current&&!active.controller.signal.aborted)setResult(JSON.stringify(response,null,2));}
  catch(error){if(alive.current&&generation===epoch.current)setError(active.controller.signal.aborted?'已停止接收；不自动重试，工具可能已执行。':error instanceof Error?error.message:'工具失败，本地工作不受影响。');}
  finally{if(alive.current&&generation===epoch.current){setBusy(false);await refresh().catch(()=>setError('连接状态读取失败。'));}if(job.current===active)job.current=null;}
 }
 return <section className="section-card"><h2>工具权限与使用</h2>{!manifest?<p>连接后，可在这里查看工具并决定允许使用哪些。尚未授权时不会执行工具；简历上传、编辑和下载不受影响。</p>:<><p>目标：{info.baseUrl} · 本轮剩余{info.remaining}/5次。超时15秒，不自动重试；工具结果仅显示为数据。</p><fieldset disabled={busy}><legend>核实并明确允许的只读名单</legend>{manifest.tools.map(item=><div key={item.name}><label><input type="checkbox" disabled={!item.eligible} checked={names.includes(item.name)} onChange={event=>{setNames(current=>event.target.checked?[...current,item.name]:current.filter(name=>name!==item.name));setVerified(false);}}/>{item.name}{!item.eligible&&' · 未声明只读/非破坏，禁止调用'}</label><p>{item.description}</p><details><summary>参数结构（只支持有限结构，禁止额外参数）</summary><pre>{JSON.stringify(item.inputSchema,null,2)}</pre></details></div>)}<label><input type="checkbox" checked={verified} onChange={event=>setVerified(event.target.checked)}/>我已核实这个可信服务的所选工具只读；工具自称只读不是我的授权。</label><button disabled={!verified} onClick={()=>void approve()}>批准此清单</button><label>允许的工具<select value={tool} onChange={event=>{setTool(event.target.value);setConsent(false);}}><option value="">请选择</option>{info.approved.map(name=><option key={name}>{name}</option>)}</select></label><label>本次发送的完整JSON参数<textarea maxLength={16000} value={args} onChange={event=>{setArgs(event.target.value);setConsent(false);}}/></label><p>只发送上面的参数，不自动附加简历、照片或Key；若粘贴了私人内容，该内容会发送至上述目标。</p><label><input type="checkbox" checked={consent} onChange={event=>setConsent(event.target.checked)}/>允许把本次参数发送给上述工具；不执行外部写入。</label><button disabled={!consent||!info.approved.includes(tool)||info.remaining<=0} onClick={()=>void call()}>执行一次只读调用</button></fieldset>{busy&&<button onClick={()=>{const active=job.current;active?.controller.abort();if(active)void api.write('/api/mcp/cancel',{requestId:active.id}).catch(()=>setError('取消未获本机确认。'));}}>取消接收</button>}<p>清单/参数变化会在调用前重新发现核对；额度用完后重新发现并批准，开启下一轮。</p></>}{error&&<p role="alert">{error}</p>}{result&&<details open><summary>不可信工具结果 · 仅供核对，不自动应用或继续调用</summary><pre>{result}</pre></details>}</section>;
}
